//! Radial fields generated by one Escentron.
//!
//! The field laws are hypotheses of Simplification Theory, not measured laws.
//! Positive radial direction points away from the source particle.
use crate::{ModelConstants, ParticleState, ValidationError, Vector3};

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum FieldError {
    InvalidInput(ValidationError),
    CoincidentPositions,
    NonFiniteResult,
}

impl From<ValidationError> for FieldError {
    fn from(value: ValidationError) -> Self { Self::InvalidInput(value) }
}

impl std::fmt::Display for FieldError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidInput(err) => err.fmt(f),
            Self::CoincidentPositions => write!(f, "the field is undefined at the source position"),
            Self::NonFiniteResult => write!(f, "field calculation exceeded finite numerical range"),
        }
    }
}

impl std::error::Error for FieldError {}

/// Field components at an observation point. Gravitational and levitational
/// values are nonnegative magnitudes; the net radial field is signed:
/// negative means inward and positive means outward.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct RadialField {
    pub distance: f64,
    pub gravitational: f64,
    pub levitational: f64,
    pub net_radial: f64,
    pub net_vector: Vector3,
}

/// Evaluate f_g = G*m/r² (inward) and f_l = G*p/r³ (outward).
///
/// The net is their radial superposition only. This does NOT specify how a
/// second particle responds, and must not be interpreted as its acceleration.
pub fn field_at(
    source: &ParticleState,
    observation: Vector3,
    constants: &ModelConstants,
) -> Result<RadialField, FieldError> {
    source.validate()?;
    constants.validate()?;
    if !observation.is_finite() {
        return Err(ValidationError::NotFinite("observation").into());
    }

    let dx = observation.x - source.position.x;
    let dy = observation.y - source.position.y;
    let dz = observation.z - source.position.z;
    if !dx.is_finite() || !dy.is_finite() || !dz.is_finite() {
        return Err(FieldError::NonFiniteResult);
    }

    // hypot is more robust than sqrt(dx*dx + dy*dy + dz*dz).
    let distance = dx.hypot(dy).hypot(dz);
    if distance == 0.0 { return Err(FieldError::CoincidentPositions); }
    if !distance.is_finite() { return Err(FieldError::NonFiniteResult); }

    let inv_r = 1.0 / distance;
    let grav = ((constants.g * inv_r) * source.mass) * inv_r;
    let lev = (((constants.g * inv_r) * source.pulse) * inv_r) * inv_r;
    let net = lev - grav;
    if !grav.is_finite() || !lev.is_finite() || !net.is_finite() {
        return Err(FieldError::NonFiniteResult);
    }
    let direction = Vector3::new(dx * inv_r, dy * inv_r, dz * inv_r);
    let net_vector = Vector3::new(
        net * direction.x, net * direction.y, net * direction.z,
    );
    if !net_vector.is_finite() { return Err(FieldError::NonFiniteResult); }

    Ok(RadialField {
        distance,
        gravitational: grav,
        levitational: lev,
        net_radial: net,
        net_vector,
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn source() -> ParticleState {
        ParticleState {
            position: Vector3::ZERO,
            velocity: Vector3::ZERO,
            mass: 2.0,
            pulse: 6.0,
        }
    }

    fn constants() -> ModelConstants {
        ModelConstants {
            g: 1.0, k_g: 1.0, k_l: 1.0, k_k: 1.0, cosmic_energy: 100.0,
        }
    }

    fn approx(a: f64, b: f64) {
        assert!((a - b).abs() < 1e-12, "{a} is not close to {b}");
    }

    #[test]
    fn at_neutral_radius_net_field_vanishes() {
        let f = field_at(&source(), Vector3::new(3.0, 0.0, 0.0), &constants()).unwrap();
        approx(f.gravitational, 2.0 / 9.0);
        approx(f.levitational, 2.0 / 9.0);
        approx(f.net_radial, 0.0);
        approx(f.net_vector.x, 0.0);
    }

    #[test]
    fn near_source_field_points_outward() {
        let f = field_at(&source(), Vector3::new(1.0, 0.0, 0.0), &constants()).unwrap();
        approx(f.net_radial, 4.0);
        approx(f.net_vector.x, 4.0);
    }

    #[test]
    fn far_from_source_field_points_inward() {
        let f = field_at(&source(), Vector3::new(4.0, 0.0, 0.0), &constants()).unwrap();
        assert!(f.net_radial < 0.0);
        assert!(f.net_vector.x < 0.0);
    }

    #[test]
    fn field_direction_uses_three_dimensions() {
        let f = field_at(&source(), Vector3::new(0.0, -4.0, 0.0), &constants()).unwrap();
        approx(f.net_vector.x, 0.0);
        assert!(f.net_vector.y > 0.0);
        approx(f.net_vector.z, 0.0);
    }

    #[test]
    fn coincident_points_are_rejected() {
        assert_eq!(
            field_at(&source(), Vector3::ZERO, &constants()),
            Err(FieldError::CoincidentPositions)
        );
    }

    #[test]
    fn non_finite_observation_is_rejected() {
        assert_eq!(
            field_at(&source(), Vector3::new(f64::NAN, 0.0, 0.0), &constants()),
            Err(FieldError::InvalidInput(ValidationError::NotFinite("observation")))
        );
    }

    #[test]
    fn g_zero_gives_zero_field() {
        let mut c = constants();
        c.g = 0.0;
        let f = field_at(&source(), Vector3::new(1.0, 0.0, 0.0), &c).unwrap();
        assert_eq!(f.net_vector, Vector3::ZERO);
    }
}
